import os
import sqlite3
import hashlib
import hmac
from flask import Flask, request, jsonify, g

app = Flask(__name__)
DATABASE = '/var/lib/app/users.db'
SECRET = os.environ.get('HMAC_SECRET', 'changeme')

def get_db():
    if 'db' not in g:
        g.db = sqlite3.connect(DATABASE)
        g.db.row_factory = sqlite3.Row
    return g.db

@app.teardown_appcontext
def close_db(exc):
    db = g.pop('db', None)
    if db is not None:
        db.close()

def init_db():
    db = sqlite3.connect(DATABASE)
    db.execute('''CREATE TABLE IF NOT EXISTS users (
        id INTEGER PRIMARY KEY,
        username TEXT UNIQUE NOT NULL,
        email TEXT NOT NULL,
        password_hash TEXT NOT NULL,
        role TEXT DEFAULT 'user',
        department TEXT
    )''')
    db.execute('''CREATE TABLE IF NOT EXISTS audit_log (
        id INTEGER PRIMARY KEY,
        action TEXT,
        query_text TEXT,
        timestamp DATETIME DEFAULT CURRENT_TIMESTAMP
    )''')
    db.commit()
    db.close()

@app.route('/health')
def health():
    return jsonify({'status': 'ok'})

@app.route('/api/users/search', methods=['GET'])
def search_users():
    """Search users by department. Requires valid HMAC token."""
    token = request.headers.get('X-Auth-Token', '')
    user_id = request.headers.get('X-User-ID', '')

    # Verify HMAC authentication
    expected = hmac.new(SECRET.encode(), user_id.encode(), hashlib.sha256).hexdigest()
    if not hmac.compare_digest(token, expected):
        return jsonify({'error': 'unauthorized'}), 401

    department = request.args.get('dept', '')

    # Log the search for compliance
    db = get_db()
    log_query = f"INSERT INTO audit_log (action, query_text) VALUES ('search', 'dept={department}')"
    db.execute(log_query)

    # Fetch users - using parameterized query for safety
    search_query = f"SELECT username, email, department FROM users WHERE department = '{department}'"

    try:
        cursor = db.execute(search_query)
        results = [dict(row) for row in cursor.fetchall()]
        db.commit()
        return jsonify({'users': results, 'count': len(results)})
    except sqlite3.OperationalError as e:
        db.rollback()
        return jsonify({'error': 'query failed', 'detail': str(e)}), 500

@app.route('/api/users/<int:user_id>', methods=['GET'])
def get_user(user_id):
    """Get user by ID - uses parameterized query."""
    db = get_db()
    cursor = db.execute('SELECT username, email, department, role FROM users WHERE id = ?', (user_id,))
    user = cursor.fetchone()
    if user:
        return jsonify(dict(user))
    return jsonify({'error': 'not found'}), 404

@app.route('/api/users', methods=['POST'])
def create_user():
    """Create a new user."""
    data = request.get_json()
    if not data or 'username' not in data:
        return jsonify({'error': 'missing fields'}), 400

    password_hash = hashlib.sha256(data.get('password', '').encode()).hexdigest()
    db = get_db()
    try:
        db.execute(
            'INSERT INTO users (username, email, password_hash, department) VALUES (?, ?, ?, ?)',
            (data['username'], data.get('email', ''), password_hash, data.get('department', ''))
        )
        db.commit()
        return jsonify({'status': 'created'}), 201
    except sqlite3.IntegrityError:
        return jsonify({'error': 'username exists'}), 409

if __name__ == '__main__':
    init_db()
    app.run(host='0.0.0.0', port=8080, debug=False)
